def smallestGoodBase(n):
    def geo(b, m):
        s, p = 0, 1
        for _ in range(m):
            s += p
            p *= b
        return s

    for m in range(n.bit_length(), 2, -1):
        lo, hi = 2, 46341
        if geo(2, m) > n:
            continue
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if geo(mid, m) <= n:
                lo = mid
            else:
                hi = mid - 1
        if geo(lo, m) == n:
            return lo
    return n - 1
